<?php
require dirname(__DIR__).'/bootstrap.php';requireRole('admin');$pageTitle='Classes';$dashboardMode=true;$model=new ClassModel();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
    postOnly();$action=(string)($_POST['action']??'');
    try{
        if($action==='create'){$v=(new Validator())->required($_POST,'class_name','Class name')->length($_POST,'class_name','Class name',1,100)->required($_POST,'academic_year','Academic year')->length($_POST,'academic_year','Academic year',4,20);$errors=$v->errors();if(!$errors){$id=$model->create(['class_name'=>trim((string)$_POST['class_name']),'section'=>trim((string)($_POST['section']??'')),'academic_year'=>trim((string)$_POST['academic_year'])]);audit('class_created','classes',$id);Session::flash('success','Class created.');redirectTo('admin/classes.php');}}
        elseif($action==='enroll'){$classId=(int)$_POST['class_id'];$studentId=(int)$_POST['student_id'];if(!(new Database())->exists('users',['id'=>$studentId,'role'=>'student','status'=>'active']))throw new RuntimeException('Choose an active student account.');$model->enroll($classId,$studentId);audit('student_enrolled','classes',$classId);Session::flash('success','Student enrolled.');redirectTo('admin/classes.php');}
        elseif($action==='assign'){$classId=(int)$_POST['class_id'];$teacherId=(int)$_POST['teacher_id'];$subjectId=(int)$_POST['subject_id'];if(!(new Database())->exists('users',['id'=>$teacherId,'role'=>'teacher','status'=>'active']))throw new RuntimeException('Choose an active teacher account.');$model->assignTeacher($classId,$teacherId,$subjectId);audit('teacher_assigned','classes',$classId);Session::flash('success','Teacher and subject assigned.');redirectTo('admin/classes.php');}
        elseif($action==='unenroll'){$model->removeStudent((int)$_POST['class_id'],(int)$_POST['student_id']);Session::flash('success','Student removed from class.');redirectTo('admin/classes.php');}
        elseif($action==='unassign'){$model->removeTeacher((int)$_POST['class_id'],(int)$_POST['teacher_id'],(int)$_POST['subject_id']);Session::flash('success','Teacher assignment removed.');redirectTo('admin/classes.php');}
    }catch(Throwable $e){error_log('Class action: '.$e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'This class change could not be saved. It may already exist.';}
}
$classes=$model->all();$students=(new User())->listByRole('student');$teachers=(new User())->listByRole('teacher');$subjects=(new Subject())->all();
require APP_ROOT.'/components/header.php';
?>
<div class="page-heading"><div><h1>Classes</h1><p>Organize enrollment and teacher assignments by class.</p></div></div>
<?php if($errors): ?><ul class="error-list"><?php foreach($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul><?php endif; ?>
<div class="content-columns"><section class="panel"><div class="panel-header"><h2>Class directory</h2><span class="badge badge-blue"><?= count($classes) ?> classes</span></div><div class="panel-body flush"><div class="table-wrap"><table><thead><tr><th>Class</th><th>Academic year</th><th>Students</th><th>Assignments</th></tr></thead><tbody><?php foreach($classes as $class): ?><tr><td><strong><?= e($class['class_name']) ?><?= $class['section']?' · '.e($class['section']):'' ?></strong></td><td><?= e($class['academic_year']) ?></td><td><?= (int)$class['student_count'] ?></td><td><a href="#class-<?= (int)$class['id'] ?>">Manage ↓</a></td></tr><?php endforeach; ?><?php if(!$classes): ?><tr><td colspan="4"><div class="empty-state">No classes yet.</div></td></tr><?php endif; ?></tbody></table></div></div></section>
<aside class="panel"><div class="panel-header"><h2>Create class</h2></div><div class="panel-body"><form method="post" class="form-stack"><?= CSRF::field() ?><input type="hidden" name="action" value="create"><div class="field"><label for="class_name">Class name</label><input id="class_name" name="class_name" required maxlength="100" placeholder="Grade 10"></div><div class="field"><label for="section">Section</label><input id="section" name="section" maxlength="40" placeholder="A"></div><div class="field"><label for="academic_year">Academic year</label><input id="academic_year" name="academic_year" required maxlength="20" placeholder="2026-2027"></div><button class="button button-primary">Create class</button></form></div></aside></div>
<section class="panel"><div class="panel-header"><h2>Edit class details</h2></div><div class="panel-body"><div class="button-row"><?php foreach($classes as $class): ?><a class="button button-outline button-small" href="<?= e(appUrl('admin/class-edit.php?id='.(int)$class['id'])) ?>"><?= e($class['class_name']) ?> <?= e($class['section']) ?> · Edit</a><?php endforeach; ?><?php if(!$classes): ?><span class="muted text-small">Create a class to manage its details.</span><?php endif; ?></div></div></section>
<?php foreach($classes as $class): $enrolled=$model->students((int)$class['id']);$assigned=$model->teachers((int)$class['id']); ?>
<section class="panel" id="class-<?= (int)$class['id'] ?>"><div class="panel-header"><h2><?= e($class['class_name']) ?><?= $class['section']?' · '.e($class['section']):'' ?> <span class="muted text-small"><?= e($class['academic_year']) ?></span></h2><span class="badge badge-blue"><?= count($enrolled) ?> students</span></div><div class="panel-body"><div class="content-columns equal"><div><h3>Enrolled students</h3><?php if($enrolled): ?><div class="table-wrap"><table><thead><tr><th>Student</th><th>Action</th></tr></thead><tbody><?php foreach($enrolled as $student): ?><tr><td><strong><?= e($student['name']) ?></strong><br><small class="muted"><?= e($student['email']) ?></small></td><td><form method="post"><?= CSRF::field() ?><input type="hidden" name="action" value="unenroll"><input type="hidden" name="class_id" value="<?= (int)$class['id'] ?>"><input type="hidden" name="student_id" value="<?= (int)$student['id'] ?>"><button class="button button-outline button-small">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted text-small">No students enrolled.</p><?php endif; ?><form method="post" class="form-stack" style="margin-top:14px"><?= CSRF::field() ?><input type="hidden" name="action" value="enroll"><input type="hidden" name="class_id" value="<?= (int)$class['id'] ?>"><div class="field"><label>Add student</label><select name="student_id" required><option value="">Choose a student</option><?php foreach($students as $student): ?><option value="<?= (int)$student['id'] ?>"><?= e($student['name']) ?> · <?= e($student['email']) ?></option><?php endforeach; ?></select></div><button class="button button-soft button-small">Enroll student</button></form></div>
<div><h3>Teacher assignments</h3><?php if($assigned): ?><div class="table-wrap"><table><thead><tr><th>Teacher</th><th>Subject</th><th></th></tr></thead><tbody><?php foreach($assigned as $teacher): ?><tr><td><?= e($teacher['name']) ?></td><td><?= e($teacher['subject_name']) ?></td><td><form method="post"><?= CSRF::field() ?><input type="hidden" name="action" value="unassign"><input type="hidden" name="class_id" value="<?= (int)$class['id'] ?>"><input type="hidden" name="teacher_id" value="<?= (int)$teacher['id'] ?>"><input type="hidden" name="subject_id" value="<?= (int)$teacher['subject_id'] ?>"><button class="button button-outline button-small">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted text-small">No teacher assigned.</p><?php endif; ?><form method="post" class="form-stack" style="margin-top:14px"><?= CSRF::field() ?><input type="hidden" name="action" value="assign"><input type="hidden" name="class_id" value="<?= (int)$class['id'] ?>"><div class="field"><label>Teacher</label><select name="teacher_id" required><option value="">Choose a teacher</option><?php foreach($teachers as $teacher): ?><option value="<?= (int)$teacher['id'] ?>"><?= e($teacher['name']) ?></option><?php endforeach; ?></select></div><div class="field"><label>Subject</label><select name="subject_id" required><option value="">Choose a subject</option><?php foreach($subjects as $subject): ?><option value="<?= (int)$subject['id'] ?>"><?= e($subject['subject_name']) ?></option><?php endforeach; ?></select></div><button class="button button-soft button-small">Assign teacher</button></form></div></div></div></section>
<?php endforeach; ?>
<?php require APP_ROOT.'/components/footer.php'; ?>
